import{_ as e,c as n,o as r,a0 as i}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"no/blog/pre-shot-routines.md","filePath":"no/blog/pre-shot-routines.md"}');const a=e({name:"no/blog/pre-shot-routines.md"},[["render",function(e,t,a,l,s,o){return r(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="bygge-rutiner-før-opptak" tabindex="-1">Bygge rutiner før opptak <a class="header-anchor" href="#bygge-rutiner-før-opptak" aria-label="Permalink to &quot;Bygge rutiner før opptak&quot;">​</a></h1><p>Forskjellen mellom et godt kast og et fantastisk kast skjer ofte før kulen forlater hånden din. En godt utformet rutine før kasting er ankeret ditt i konkurransens storm – en pålitelig sekvens som forbereder sinn og kropp for optimal ytelse.</p><h2 id="hvorfor-rutiner-før-inntak-er-viktige" tabindex="-1">Hvorfor rutiner før inntak er viktige <a class="header-anchor" href="#hvorfor-rutiner-før-inntak-er-viktige" aria-label="Permalink to &quot;Hvorfor rutiner før inntak er viktige&quot;">​</a></h2><p>Eliteutøvere i alle idretter bruker rutiner før kast. I petanque, hvor hvert kast er diskret og det kan bygges opp press mellom slagene, tjener rutinene flere formål:</p><ul><li><strong>Konsistens</strong>: Samme forberedelse fører til mer konsistent utførelse</li><li><strong>Fokus</strong>: Gir tankene dine en konstruktiv oppgave i stedet for å bekymre seg</li><li><strong>Overgang</strong>: Hjelper deg med å gå fra å tenke til å gjøre</li><li><strong>Presshåndtering</strong>: Kjente handlinger beroliger nervesystemet</li><li><strong>Tilbakestill</strong>: Fjerner det forrige bildet fra tankene dine</li></ul><h2 id="anatomien-til-en-effektiv-rutine" tabindex="-1">Anatomien til en effektiv rutine <a class="header-anchor" href="#anatomien-til-en-effektiv-rutine" aria-label="Permalink to &quot;Anatomien til en effektiv rutine&quot;">​</a></h2><p>En god rutine før inntak har tre faser:</p><h3 id="fase-1-vurdering-5–10-sekunder" tabindex="-1">Fase 1: Vurdering (5–10 sekunder) <a class="header-anchor" href="#fase-1-vurdering-5–10-sekunder" aria-label="Permalink to &quot;Fase 1: Vurdering (5–10 sekunder)&quot;">​</a></h3><ul><li>Les terrenget</li><li>Visualiser det tiltenkte resultatet</li><li>Velg kastetype</li><li>Forplikt deg til avgjørelsen</li></ul><h3 id="fase-2-forberedelse-5–10-sekunder" tabindex="-1">Fase 2: Forberedelse (5–10 sekunder) <a class="header-anchor" href="#fase-2-forberedelse-5–10-sekunder" aria-label="Permalink to &quot;Fase 2: Forberedelse (5–10 sekunder)&quot;">​</a></h3><ul><li>Ta din posisjon</li><li>Finn grepet ditt</li><li>Få ro i pusten din</li><li>Føl vekten av kulen</li></ul><h3 id="fase-3-utførelse-3–5-sekunder" tabindex="-1">Fase 3: Utførelse (3–5 sekunder) <a class="header-anchor" href="#fase-3-utførelse-3–5-sekunder" aria-label="Permalink to &quot;Fase 3: Utførelse (3–5 sekunder)&quot;">​</a></h3><ul><li>Endelig fokus på målet</li><li>Stol på kroppen din</li><li>Slipp slipp uten tanke</li><li>Følg opp naturlig</li></ul><h2 id="bygge-din-personlige-rutine" tabindex="-1">Bygge din personlige rutine <a class="header-anchor" href="#bygge-din-personlige-rutine" aria-label="Permalink to &quot;Bygge din personlige rutine&quot;">​</a></h2><h3 id="trinn-1-observer-dine-naværende-mønstre" tabindex="-1">Trinn 1: Observer dine nåværende mønstre <a class="header-anchor" href="#trinn-1-observer-dine-naværende-mønstre" aria-label="Permalink to &quot;Trinn 1: Observer dine nåværende mønstre&quot;">​</a></h3><p>Før du lager en ny rutine, legg merke til hva du allerede gjør:</p><ul><li>Hva gjør du før vellykkede kast?</li><li>Hva endrer seg når du er under press?</li><li>Hva føles naturlig for deg?</li></ul><h3 id="trinn-2-design-sekvensen-din" tabindex="-1">Trinn 2: Design sekvensen din <a class="header-anchor" href="#trinn-2-design-sekvensen-din" aria-label="Permalink to &quot;Trinn 2: Design sekvensen din&quot;">​</a></h3><p>Lag en rutine som inkluderer:</p><p><strong>Fysiske elementer:</strong></p><ul><li>Hvordan du nærmer deg sirkelen</li><li>Hvordan du plukker opp og holder kulen</li><li>Din holdning og posisjonering</li><li>Et spesifikt pustemønster</li></ul><p><strong>Mentale elementer:</strong></p><ul><li>En visualisering av resultatet</li><li>Et fokusord eller en frase</li><li>Et forpliktelsespunkt (i det øyeblikket du bestemmer deg for at «dette er kastet»)</li></ul><h3 id="trinn-3-hold-det-enkelt" tabindex="-1">Trinn 3: Hold det enkelt <a class="header-anchor" href="#trinn-3-hold-det-enkelt" aria-label="Permalink to &quot;Trinn 3: Hold det enkelt&quot;">​</a></h3><p>Rutinen din bør være:</p><ul><li><strong>Kort nok</strong> til å opprettholde press (15–25 sekunder totalt)</li><li><strong>Enkelt nok</strong> til å huske når man er stresset</li><li><strong>Fleksibel nok</strong> til å tilpasse seg ulike situasjoner</li></ul><h2 id="eksempelrutiner" tabindex="-1">Eksempelrutiner <a class="header-anchor" href="#eksempelrutiner" aria-label="Permalink to &quot;Eksempelrutiner&quot;">​</a></h2><h3 id="pekerens-rutine" tabindex="-1">Pekerens rutine <a class="header-anchor" href="#pekerens-rutine" aria-label="Permalink to &quot;Pekerens rutine&quot;">​</a></h3><ol><li>Stå bak sirkelen og vurder terrenget</li><li>Visualiser kulens bane og landingssted</li><li>Gå inn i sirkelen, finn din holdning</li><li>Tre langsomme åndedrag mens du kjenner på boule</li><li>Øynene på målet, slipp</li></ol><h3 id="skytterens-rutine" tabindex="-1">Skytterens rutine <a class="header-anchor" href="#skytterens-rutine" aria-label="Permalink to &quot;Skytterens rutine&quot;">​</a></h3><ol><li>Identifiser målkulen, velg vinkelen</li><li>Visualiser effekten og resultatet</li><li>Gå inn i sirkelen med et formål</li><li>Ett dypt åndedrag, kjenn vekten</li><li>Fest blikket på målet, utfør</li></ol><h2 id="vanlige-feil-a-unnga" tabindex="-1">Vanlige feil å unngå <a class="header-anchor" href="#vanlige-feil-a-unnga" aria-label="Permalink to &quot;Vanlige feil å unngå&quot;">​</a></h2><h3 id="for-lang" tabindex="-1">For lang <a class="header-anchor" href="#for-lang" aria-label="Permalink to &quot;For lang&quot;">​</a></h3><p>Hvis rutinen din tar mer enn 30 sekunder, tenker du for mye. Lange rutiner gir angsten mer tid til å bygge seg opp.</p><h3 id="for-stiv" tabindex="-1">For stiv <a class="header-anchor" href="#for-stiv" aria-label="Permalink to &quot;For stiv&quot;">​</a></h3><p>Hvis en avbrudd ødelegger rutinen din, er den for skjør. Bygg inn fleksibilitet – hvis noe forstyrrer konsentrasjonen din, ha en utløser som kan resete den.</p><h3 id="hopping-under-press" tabindex="-1">Hopping under press <a class="header-anchor" href="#hopping-under-press" aria-label="Permalink to &quot;Hopping under press&quot;">​</a></h3><p>Rutinen er viktigst når presset er høyest. Hvis du dropper den når du er stresset, mister du dens beskyttende fordeler.</p><h3 id="fokus-pa-mekanikk" tabindex="-1">Fokus på mekanikk <a class="header-anchor" href="#fokus-pa-mekanikk" aria-label="Permalink to &quot;Fokus på mekanikk&quot;">​</a></h3><p>Rutinen din bør avsluttes med fokus på resultatet, ikke på teknikk. «Treffe målet», ikke «holde albuen rett».</p><h2 id="øve-pa-rutinen-din" tabindex="-1">Øve på rutinen din <a class="header-anchor" href="#øve-pa-rutinen-din" aria-label="Permalink to &quot;Øve på rutinen din&quot;">​</a></h2><h3 id="i-trening" tabindex="-1">I trening <a class="header-anchor" href="#i-trening" aria-label="Permalink to &quot;I trening&quot;">​</a></h3><ul><li>Bruk hele rutinen din for hvert kast, selv de som er mer tilfeldige</li><li>Ta tiden på deg selv for å sikre konsistens</li><li>Øv med distraksjoner for å bygge motstandskraft</li></ul><h3 id="bygningsautomatikk" tabindex="-1">Bygningsautomatikk <a class="header-anchor" href="#bygningsautomatikk" aria-label="Permalink to &quot;Bygningsautomatikk&quot;">​</a></h3><p>Målet er at rutinen din skal bli automatisk – noe du gjør uten å tenke deg om. Dette krever repetisjon:</p><ul><li>100+ kast med samme rutine</li><li>Konsekvent bruk i ulike situasjoner</li><li>Gradvis eksponering for press samtidig som rutinen opprettholdes</li></ul><h2 id="tilpasning-til-konkurranse" tabindex="-1">Tilpasning til konkurranse <a class="header-anchor" href="#tilpasning-til-konkurranse" aria-label="Permalink to &quot;Tilpasning til konkurranse&quot;">​</a></h2><p>I kamper kan det hende at rutinen din trenger små justeringer:</p><ul><li><strong>Tidspress</strong>: Ha en forkortet versjon klar</li><li><strong>Værforhold</strong>: Juster fysiske elementer etter behov</li><li><strong>Øyeblikk med høyt trykk</strong>: Senk farten litt, ikke øk farten</li></ul><h2 id="tilbakestillingsrutinen" tabindex="-1">Tilbakestillingsrutinen <a class="header-anchor" href="#tilbakestillingsrutinen" aria-label="Permalink to &quot;Tilbakestillingsrutinen&quot;">​</a></h2><p>Like viktig er hva du gjør etter et kast:</p><ol><li><strong>Godta resultatet</strong> — bra eller dårlig, det er gjort</li><li><strong>Fysisk tilbakestilling</strong> — ta et skritt tilbake, rist ut spenninger</li><li><strong>Mental tilbakestilling</strong> — fjern kastet fra tankene dine</li><li><strong>Forbered deg på det neste</strong> – flytt fokuset til det som kommer</li></ol><hr><p>| <em>Relatert: <a href="/no/utdanning/mental-styrke/rutine-før-sprøyting">Veiledning for rutine før sprøyting</a> | <a href="/no/utdanning/mental-styrke/håndtering-av-press">Håndtering av press</a> | <a href="/no/utdanning/mindfulness/teknikker">Mindfulness-teknikker</a></em> |</p>',54)])])}]]);export{t as __pageData,a as default};
